sys_script_fix.script:
var loc = new GlideRecord('cmn_location');
loc.addQuery('name', 'CONTAINS', 'undefined');
loc.addQuery('sys_class_name', 'cmn_location');
loc.setLimit(2);
loc.query();

if (!gs.nil(loc.street) && !gs.nil(loc.zip) && !gs.nil(loc.state) && !gs.nil(loc.city)){

var locStreet = loc.getValue("street");
var locCity = loc.getValue("city");
var locState = loc.getValue("state");

loc.setValue('name', locStreet + ', ' + locCity + ', ' + locState);

gs.info("Location: " + loc.getValue('name') + "& Description: " + loc.getValue('u_description'));

}
